            if (((((bn + (int)(strlen(fld))) + (int)(strlen(bnm))) + (int)(strlen(bty))) + 6) >= (int)(sizeof(bbuf))) {
                break;
            }
            memcpy((bbuf + bn), fld, strlen(fld));
            bn += (int)(strlen(fld));
            bbuf[bn++] = '|';
            memcpy((bbuf + bn), bnm, strlen(bnm));
            bn += (int)(strlen(bnm));
            bbuf[bn++] = '|';
            memcpy((bbuf + bn), bty, strlen(bty));
            bn += (int)(strlen(bty));
