static int tb_block(struct backend_tir_TBuilder * tb, int n, int kind) {
    struct runtime_arena_Arena * ar;
    int sid;
    int c;
    int t;
    int saved;
    ar = tb_arena();
    sid = backend_tir_tmod_new_stmt(tb->m, kind, tb->file, tb_line(n), tb_col(n), tb->scope);
    if (sid < 0) {
        return (-1);
    }
    saved = tb->scope;
    if (tb_push_scope(tb, SC_BLOCK) < 0) {
        return (-1);
    }
    tb->m->stmts[(sid - 1)].scope = tb->scope;
    for (c = ar->nodes[n].a; c >= 0; c = ar->nodes[c].next) {
        if (ar->nodes[c].kind == N_DEFER_RUN) {
            int ck;
            int cbody;
            if (ar->nodes[c].aux < 3) {
                continue;
            }
            ck = ((ar->nodes[c].aux == 4) ? CL_ERRDEFER : CL_DEFER);
            cbody = tb_stmt(tb, ar->nodes[c].a);
            if (cbody < 0) {
                return (-1);
            }
            if (backend_tir_tmod_scope_add_cleanup(tb->m, tb->scope, ck, cbody, ((ck == CL_ERRDEFER) ? 1 : 0), tb->file, ar->nodes[c].line, ar->nodes[c].num) < 0) {
                return (-1);
            }
            continue;
        }
        t = tb_stmt(tb, c);
        if (t < 0) {
            return (-1);
        }
        if (t > 0) {
            backend_tir_tmod_stmt_add_kid(tb->m, sid, t);
        }
    }
    tb_pop_scope(tb);
    tb->scope = saved;
    return sid;
}
